edits.after:
/* See if we need to begin/extend the Tx queue. */
if (!call->send_queue || !((call->send_top + 1) & RXRPC_TXQ_MASK)) {
	if (!call->send_queue && call->tx_queue) {
		ret = -EPROTO;
		goto maybe_error;
	}

	ret = rxrpc_alloc_txqueue(sk, call);
	if (ret < 0)
		goto maybe_error;
}

